class TaskBinding{static Object value(long m,long n){return new Fraction(m,n);}static long[]parts(Object f){return new long[]{((Fraction)f).numerator(),((Fraction)f).denominator()};}static Object operation(Object a,Object b,int op){Fraction x=(Fraction)a,y=(Fraction)b;return switch(op){case 0->x.add(y);case 1->x.subtract(y);case 2->x.multiply(y);default->x.divide(y);};}static String text(Object f){return f.toString();}}
